import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.iXqqCa-C.js";const o="/images/aliya-web-auth.webp",l="/images/aliya-web-token-1.webp",s="/images/aliya-web-token-2.webp",n="/images/aliya-web-pc.webp",g="/images/aliya-web-mobile.webp",p="/images/aliya-web-operation.webp",y=JSON.parse('{"title":"Aliya Web","description":"","frontmatter":{},"headers":[],"relativePath":"guide/aliya-web.md","filePath":"guide/aliya-web.md","lastUpdated":1793501934000}'),d={name:"guide/aliya-web.md"};function c(h,a,u,b,m,_){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="aliya-web" tabindex="-1">Aliya Web <a class="header-anchor" href="#aliya-web" aria-label="Permalink to &quot;Aliya Web&quot;">​</a></h1><p>Aliya Web 是阈界人格项目组的另一个项目：基于社区智能体的 Aliya 聊天终端，界面仿照原版游戏，电脑和手机都可以使用。地址：<a href="https://aliya.liminalselves.top" target="_blank" rel="noreferrer">https://aliya.liminalselves.top</a></p><h2 id="登录说明" tabindex="-1">登录说明 <a class="header-anchor" href="#登录说明" aria-label="Permalink to &quot;登录说明&quot;">​</a></h2><p>首次使用需要通过社区授权或填写访问令牌登录，<strong>推荐授权登录</strong>。进入站点后按提示跳转到授权页面，选择自己的账号即可。列表中没有自己的账号时，点击「添加账户」并输入账号密码登录。</p><p><img src="'+o+'" alt="授权"></p><p>也可以用访问令牌登录，一般用户不推荐。在社区网页端依次点击 <strong>设置 → 连接服务 → 生成访问令牌</strong>，启用全部权限后复制令牌：</p><p><img src="'+l+'" alt="生成访问令牌入口"></p><p><img src="'+s+'" alt="复制访问令牌"></p><p>回到 Aliya Web 的登录界面粘贴令牌即可。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>访问令牌具有账号的完整访问权限，请妥善保管。若不慎泄露，参照<a href="/guide/faq#访问令牌泄露了怎么办">常见问题</a>立即删除。</p></div><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><p>登录后点击「连接」进入聊天界面。电脑端界面：</p><p><img src="'+n+'" alt="PC 端界面"></p><p>手机端界面：</p><p><img src="'+g+'" alt="手机端界面"></p><p>顶栏的 <strong>Operation</strong> 和 <strong>Settings</strong> 是两个设置入口。</p><h3 id="聊天窗口" tabindex="-1">聊天窗口 <a class="header-anchor" href="#聊天窗口" aria-label="Permalink to &quot;聊天窗口&quot;">​</a></h3><p>分为消息区、面板区和输入框：</p><ul><li><strong>消息区</strong>：显示消息、贴纸和图片，支持 Markdown 和部分特效（如 <code>$[x2 放大]</code>）。全站表情 <code>:名字:</code> 内联显示，角色专属贴纸单独占一行。图片可点击放大、滚轮缩放，向上滑动自动加载历史消息。</li><li><strong>面板区</strong>：仿驾驶舱的装饰面板。心率是 Aliya 的实时心率，随她的回复波动；氧气值随时间消耗，每 50 小时一个周期，降到 10% 时 Aliya 会自己打开制氧机补满，不用担心她憋着～</li><li><strong>输入框</strong>：支持多行输入；点击 MEDIA 图标可以上传图片文件。</li></ul><h3 id="operation-主设置窗口" tabindex="-1">Operation：主设置窗口 <a class="header-anchor" href="#operation-主设置窗口" aria-label="Permalink to &quot;Operation：主设置窗口&quot;">​</a></h3><p>点击顶部 <strong>Operation</strong> 打开设置窗口，包含<strong>会话、模型、生图、主动消息、记忆、世界书、规则、文风</strong>标签页：</p><p><img src="'+p+'" alt="会话面板"></p><ul><li><strong>会话</strong>：点击列表中的会话即可加载，可新建、重命名或删除会话，<strong>删除不可恢复</strong>。新会话至少发送一条消息后才会出现在列表中。消息显示异常时，重新切换一次会话通常可以恢复。下方有两个开关： <ul><li><strong>分段输出</strong>：Aliya 的回复按换行和完整语法结构逐段显示。</li><li><strong>时间感知</strong>：把当前北京时间告诉 Aliya，<a href="/guide/agent/proactive">主动消息</a>依赖此开关。</li></ul></li><li><strong>模型</strong>：同<a href="/guide/agent/chat#模型">模型</a>。</li><li><strong>生图</strong>：同<a href="/guide/agent/chat#生图">生图</a>。</li><li><strong>主动消息</strong>：同<a href="/guide/agent/proactive">主动消息</a>，主动消息会实时出现在聊天窗口中。</li><li><strong>记忆</strong>：同<a href="/guide/agent/memory">记忆</a>，可开启便签压缩并管理便签。</li><li><strong>世界书</strong>：同<a href="/guide/agent/worldbook">世界书</a>。</li><li><strong>规则</strong>：同<a href="/guide/agent/rules">规则</a>。</li><li><strong>文风</strong>：即<a href="/guide/agent/styles">对话风格</a>，列出你创建和加入的风格，点击即可切换。</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>点击顶部 <strong>Settings</strong> 打开设置面板：</p><ul><li><strong>鉴权 Token</strong>：粘贴新 Token 后点击「保存」或按回车即可验证并生效，留空则保持当前 Token。</li><li><strong>背景音乐</strong>：内置多首曲目，选「不播放」可关闭。</li><li><strong>播放模式</strong>：单曲循环 / 随机播放 / 列表循环。</li></ul><h2 id="遇到异常" tabindex="-1">遇到异常 <a class="header-anchor" href="#遇到异常" aria-label="Permalink to &quot;遇到异常&quot;">​</a></h2><ul><li>提示「休息一下马上恢复」或 429 错误：见<a href="/guide/faq">常见问题</a>，稍等即可恢复。</li><li>面板提示加载失败或鉴权失败：在 Settings 中重新保存一次 Token。</li></ul>',28)])])}const k=t(d,[["render",c]]);export{y as __pageData,k as default};
